import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AM everyday-crime stories.
extension FollowUpCases {
    static let batchAM: [CaseTemplate] = [gasDriveOffTwo, barBanTrespass, libraryBanScream, mowerResale, leashThreat, carClaimFalse,
                                          packageCardUse, golfCartTrespass, refusedIDAgain, oxyRefill, dineDashTwo, fenceKickAssault, walletCardGas]

    static let gasDriveOffTwo = followUp(
        key: "story.followup.gasDriveOffTwo", category: .property,
        headlines: ["Driver Skips Out on Gas Bill Again", "Second Gas Drive-Off Charge for Same Driver"],
        law: "misdLarceny", threshold: 5, spec: "Stole $71 in motor fuel from a gas station, on {DATE}.", ages: 19...58, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a different station's camera recorded {D} filling up at pump four and leaving without paying. The plate matched. {DL} says the clerk waved {D.him} off.",
        state: [E(.video, 3, "Pump Camera", "{D} pumps $71 of fuel and drives off."), E(.document, 2, "Plate Return", "The plate is registered to {D}.")],
        defense: [E(.statement, 1, "Clerk's Wave", "{D} says the clerk waved at {D.him} through the window.")],
        witnessRole: "Gas station clerk",
        exam: [.direct("What happened?", "\"{DL} pumped $71 and left.\""),
               .direct("Did you wave?", "\"I waved at a friend. {DL} was just in the line of sight.\""),
               .direct("What did you see on the camera?", "\"A car pulling up to pump four, a man filling the tank with $71 of fuel, and driving off without coming inside.\""),
               .direct("How was {DL} identified?", "\"The plate matched {DL}'s registration, and the clerk recognized the car from earlier visits.\""),
               .direct("Did anyone speak to {DL}?", "\"I did not. I was behind the counter helping another customer, and I did not see {D.him} until I checked the pump.\""),
               .direct("What happened afterward?", "\"{DL} never came back to pay. The same plate left unpaid at two more stations in the weeks after.\""),
               .cross("It could look like a wave off.", "\"Maybe. It could look like a wave off from where I stood.\""),
               .cross("{DL} came back?", "\"No. {DL} never came back.\""),
               .cross("The clerk later said {D.he} had waved?", "\"Later, yes. {D.He} says it was at a friend, and {DL} was in the line of sight.\""),
                    .cross("You cannot say what {DL} meant when {D.he} left?", "\"No. I can say {D.he} left without paying. I cannot say what was in {D.his} mind.\""), .cross("The same plate was at two other stations?", "\"It was, according to the reports. I do not know how those stations handled it.\"")],
        theory: ("{D} did it again at a new station.", "A wave misread."),
        allocution: "\"I know it looks bad that this happened twice, and I'm sorry for it. I honestly thought the clerk had waved me off at that second station, and I should have gone in and made sure. I'll pay both bills, and I won't leave a pump without settling up again.\"", truths: ("The same plate left unpaid at two more stations.", "The clerk later said {D.he} had waved at {D.him}."),
        defendant: [.direct("Why did you leave?", "\"The clerk waved. I thought we were done.\""),
               .direct("Did you pay?", "\"No. I didn't pay, and I'm sorry about that.\""),
               .direct("Did you go inside?", "\"No. I did not go in, because I thought I had permission to go.\""),
               .direct("What did you see the clerk do?", "\"A hand wave through the glass. I took it to mean it was fine.\""),
               .direct("Did you try to come back and pay?", "\"No, I did not. I should have stopped in later, and I am sorry I did not.\""),
               .direct("What did you do after you drove off?", "\"I went about my day and did not think about it. I did not realize I had left without paying until much later.\""),
               .cross("After your last case.", "\"I know. After my last case, I should have been more careful.\""),
               .cross("You didn't go in.", "\"I thought I had permission.\""),
               .cross("You did not go in.", "\"I thought I had permission.\""),
               .cross("The same plate was at two more stations.", "\"I do not remember those. I may have been confused again.\""),
                    .cross("The clerk says {D.he} was only waving at a friend.", "\"I understand now that I read the wave wrong. I should have gone in and asked.\"")],
        openings: ("A different station's camera recorded {D} filling up at pump four with $71 of fuel and driving off without paying. The plate matched {D}'s registration, and the same plate left unpaid at two more stations.", "The defense will say the clerk waved at {D} through the window and {D} took it as permission to leave. {D} never meant to steal fuel."), closings: ("Seventy-one dollars at the pump, a plate registered to {D}, and the same plate at two more stations, after {PRIOR}. {D} never came back to pay.", "A wave through a window can mean anything, and the clerk later said {D.he} had waved. The State must prove {D} meant to drive off without paying."),
        timeline: [(0, "Night: second drive-off.")], identified: "A second station's camera.", impact: nil)

    static let barBanTrespass = followUp(
        key: "story.followup.barBanTrespass", category: .property,
        headlines: ["Man Banned From Bar Returns, Charged With Trespass", "Trespass Charge After Window Case"],
        law: "trespass2", threshold: 5, spec: "Entered and remained on the premises of a bar after being notified not to enter, on {DATE}.", ages: 21...54, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the bar's owner told {D} in writing never to return. On {DATE}, {DL} walked in, ordered a beer, and was arrested when the bartender called deputies. {DL} says the owner had said the ban was over.",
        state: [E(.document, 3, "Written Ban", "A letter from the owner dated after the earlier case."), E(.statement, 2, "Bartender", "The bartender knew of the ban and called deputies.")],
        defense: [E(.statement, 1, "Truce", "{D} says the owner told {D.him} \"all forgiven\" two weeks earlier.")],
        witnessRole: "Bartender",
        exam: [.direct("What happened?", "\"{DL} walked in and ordered a beer. I knew about the ban.\""),
               .direct("Did you call deputies?", "\"I called deputies right away, as soon as it happened.\""),
               .direct("How did you know {DL} was banned?", "\"The owner posted a copy of the written ban behind the bar, dated after the earlier case, and told all of us at the staff meeting.\""),
               .direct("How did {DL} behave?", "\"Calmly. {D.He} did not cause any trouble, and {D.he} sat at the bar until the deputies arrived.\""),
               .direct("What did the owner tell you about the ban?", "\"The owner had said, 'stay away for a year.' I never heard the ban was lifted.\""),
               .direct("Was the ban posted anywhere in the bar?", "\"Yes. The owner taped a copy by the register, with {DL}'s name and the date, so staff would recognize {D.him}.\""),
                    .cross("The owner said all forgiven?", "\"I didn't hear that. The owner never said all was forgiven in front of me.\""),
               .cross("{D.He} didn't cause trouble.", "\"No. {D.He} didn't cause any trouble that night.\""),
               .cross("The owner and {DL} shook hands at a church supper?", "\"I have heard that. I do not know what was said.\""),
                    .cross("The bartender called deputies even though {DL} did not cause trouble?", "\"I did, because the owner told us to call if {D.he} came in. That was the instruction.\""), .cross("You did not talk to {DL} before calling?", "\"I did not. I recognized the name, and I called right away.\"")],
        theory: ("{D} walked into a bar {D.he} was banned from.", "A forgiven dispute."),
        allocution: "\"I walked in that night because I thought the owner and I had made peace after the last time. I never saw the letter as the last word, and I was wrong not to check first. I'm sorry for the trouble I caused the bartender, and I won't go back there again.\"", truths: ("The owner had said, \"stay away for a year.\"", "The owner and {DL} had shaken hands at a church supper."),
        defendant: [.direct("Why did you go?", "\"The owner told me all was forgiven.\""),
               .direct("Was it written?", "\"No. It wasn't written down, only said out loud.\""),
               .direct("Why did you go to the bar?", "\"The owner told me all was forgiven two weeks before. We shook hands at a church supper.\""),
               .direct("Was the forgiveness written down?", "\"No. It was only said out loud, and I took {D.him} at {D.his} word.\""),
               .direct("What did you do when you walked in?", "\"Ordered a beer and sat down. I did not hide or sneak in.\""),
               .direct("Did you know about the written ban?", "\"I had the written ban at home. I believed it was over after what the owner told me.\""),
               .cross("You had a written ban.", "\"Yes, I had the written ban. But the owner told me later that it was over, and I took {D.him} at {D.his} word.\""),
               .cross("After your last case.", "\"I know. After my last case, I should have been more careful.\""),
               .cross("You did not ask for anything in writing.", "\"I did not. It was a handshake at church, and I did not think I needed paper.\""),
                    .cross("The ban letter had your name on it.", "\"It did. I read it when I got it, and I kept it in a drawer.\""), .cross("You did not ask the owner to put the forgiveness in writing.", "\"I did not. We shook hands at church, and I did not think I needed paper.\"")],
        openings: ("The bar's owner told {D} in writing never to return after the earlier case. On {DATE}, {D} walked in, ordered a beer, and was arrested when the bartender called deputies.", "The defense will say the owner told {D} 'all forgiven' two weeks earlier, at a church supper, and {D} reasonably believed the ban was over. {D} caused no trouble."), closings: ("A written ban from the owner, a bartender who knew of it, and {D} at the bar ordering a beer, after {PRIOR}. Whatever was said at a church supper, the letter was never withdrawn.", "The owner shook {D}'s hand and said all was forgiven. The State must prove {D} knew the ban was still in effect when {D.he} walked in."),
        timeline: [(0, "Evening: {DL} returns to the bar.")], identified: "The bartender's call.", impact: nil)

    static let libraryBanScream = followUp(
        key: "story.followup.libraryBanScream", category: .publicOrder,
        headlines: ["Man Banned From Library Disrupts Bus Stop Outside", "Disorderly Conduct Charge Follows Trespass Case"],
        law: "disorderly", threshold: 5, spec: "Engaged in disorderly conduct in a public place, yelling at passersby and blocking a bus shelter, on {DATE}.", ages: 22...66, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} stood outside the library for an hour yelling that the staff had \"stolen\" his reading. A bus driver reported {DL} blocking the shelter and shouting at riders. {D.He} says he was speaking to himself.",
        state: [E(.video, 2, "Bus Camera", "{D} stands in the shelter, shouting, while riders wait in the street."), E(.statement, 2, "Driver", "{D} blocked the doors for two minutes.")],
        defense: [E(.document, 2, "Medical Note", "{D} has a documented anxiety disorder and sometimes talks aloud.")],
        witnessRole: "Bus driver",
        exam: [.direct("What did you see?", "\"A man yelling in the shelter. Riders stayed in the street.\""),
               .direct("Did he block the doors?", "\"He blocked the doors for about two minutes.\""),
               .direct("What was the bus route at that stop?", "\"A route that stops at the shelter outside the library every twenty minutes. I was on the afternoon run, with about a dozen riders aboard.\""),
               .direct("What did you do when he blocked the doors?", "\"I opened the doors and asked him to step aside. He did not move for about two minutes, and I called dispatch.\""),
               .direct("What did you learn about the man afterward?", "\"That he had been banned from the library after the earlier case. I recognized the name from the notice posted at the front desk.\""),
               .direct("What did the camera on the bus record?", "\"{DL} standing in the shelter with arms raised, and riders waiting out in the street. The audio picked up shouting, though not the words.\""),
                    .cross("Was he threatening anyone?", "\"Not directly. He wasn't threatening anyone that I heard.\""),
               .cross("He was talking to himself.", "\"Loudly. He was talking to himself, and he was loud about it.\""),
               .cross("{DL} did not touch anyone, did {D.he}?", "\"No. {D.He} never touched a rider or me. {D.He} stood in the way and shouted.\""),
               .cross("{DL} was yelling at the building, not at the riders?", "\"Mostly, yes. A few riders thought it was aimed at them, and they stayed in the street.\""),
               .cross("You did not call for deputies right away?", "\"I called dispatch and waited to see whether he would move. He did after two minutes, and a deputy came a little later.\"")],
        theory: ("{D} shouted at riders and blocked a bus shelter.", "A man with an anxiety disorder, talking aloud."),
        allocution: "\"I'm trying to get help for what I'm going through, and I know that morning I let it get the better of me. I raised my voice outside the library and at the bus shelter, and that wasn't fair to the staff or the riders. I'm sorry, and I'm working on keeping calm.\"", truths: ("{DL} had skipped his medication that week.", "He had been waiting for a case worker who never came."),
        defendant: [.direct("What happened?", "\"I was upset about the ban.\""), .direct("Were you shouting at people?", "\"I was shouting at the building, not at any person.\""),
                    .direct("Why were you outside the library that afternoon?", "\"I wanted to get back to my reading. I was upset about the ban and I had no place else to go.\""), .direct("What were you saying?", "\"That the staff had stolen my reading. I meant my library card and the books I had on hold, and I said it over and over.\""), .direct("Do you take medication for anxiety?", "\"I do, and I had skipped it that week. When I do, I talk out loud without noticing, and I get loud when I am upset.\""), .direct("Why did you stand in the shelter?", "\"It was raining and I did not want to get wet. I did not know I was blocking the doors of a bus.\""),
                    .cross("Riders stayed in the street.", "\"I didn't mean to scare anyone.\""), .cross("You were banned.", "\"I know. I was banned, and I went anyway.\""),
                    .cross("The bus driver says you blocked the doors for two minutes.", "\"I did not realize it was that long. I moved as soon as I understood what was happening.\""), .cross("Riders waited in the street instead of the shelter.", "\"I did not mean to scare anyone. I did not see them until the driver spoke to me.\""), .cross("You knew you were banned from the library.", "\"I did. I went there anyway because my books were inside, and I did not think I could just walk away from them.\"")],
        openings: ("{D} stood outside the library for an hour yelling that the staff had 'stolen' {D.his} reading, after being banned, and when a bus arrived {D} blocked the shelter and the doors for two minutes while riders waited in the street.", "The defense will say {D} has a documented anxiety disorder, had skipped {D.his} medication, and was talking aloud to {D.himself}. {D} was waiting for a case worker who never came, and never touched anyone."), closings: ("A banned man stood in a bus shelter for an hour shouting at a library, blocked the doors for two minutes, and sent riders into the street. {D} was back in court after {PRIOR} for refusing to go.", "A man with an anxiety disorder who had missed his medication talked loudly to himself in the rain and touched no one. The State must prove {D} meant to disturb the riders and not merely that {D.he} was ill."),
        timeline: [(0, "Midday: {DL} outside the library; the bus arrives.")], identified: "The bus driver's report.", impact: nil)

    static let mowerResale = followUp(
        key: "story.followup.mowerResale", category: .property,
        headlines: ["Neighbor's Mower Surfaces at Flea Market; Seller Charged", "Second Mower Case for Same Neighbor Dispute"],
        law: "possStolen", threshold: 5, spec: "Possessed a push mower valued at $320 belonging to {V}, knowing and having reasonable grounds to believe it stolen, on {DATE}.", ages: 28...68, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s push mower vanished from a shed. It turned up at a weekend flea market where {D} was the seller. {D.He} says {D.he} found it at the curb.",
        state: [E(.physical, 3, "The Mower", "{V}'s mower with a serial match, for sale at {D}'s table.", .search), E(.statement, 2, "Buyer", "A buyer says {D} asked $80 and said it was his own.")],
        defense: [E(.statement, 1, "Curb", "{D} says it was set out for trash.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("Where did you find it?", "\"On {DL}'s table at the flea market.\""), .direct("What did {D.he} say?", "\"That it was {D.his} own.\""),
               .direct("How did the mower come to your attention?", "\"{V} reported a push mower missing from a shed. A week later a weekend flea market had one for sale that matched the description.\""), .direct("Who was selling it?", "\"{DL}, at a table near the entrance. The mower sat in front of the table with an $80 price on a piece of tape.\""), .direct("What did the buyer say?", "\"A man who asked about it said {DL} told him it was {D.his} own, bought new, and that {D.he} wanted $80.\""), .direct("What did you find on the mower?", "\"The serial plate. It matched the serial number on {V}'s report. I checked it twice against the paperwork.\""),
                    .cross("{D.He} said it was on the curb.", "\"That's a different story from the buyer's.\""), .cross("Serial plate matched?", "\"It did. The serial plate matched the one on the report.\""),
                    .cross("{DL} says it was at the curb for trash?", "\"That is what {D.he} told me. {V}'s son had actually set it out for trash, and that is what {V} said when I asked.\""), .cross("{DL} did not hide the mower, did {D.he}?", "\"No. It was in plain sight at a public market, with a price on it.\""), .cross("{DL} was seen carrying a mower from {V}'s shed?", "\"A neighbor said so. I did not see that, and I have not confirmed the neighbor's account.\"")],
        theory: ("{D} sold a neighbor's mower and said it was his.", "A curbside find."),
        allocution: "\"I found that mower at the curb and thought nobody wanted it, so I sold it at the flea market. I should have asked around before I put a price on it, and I know how that looks after my last case. I'm sorry, and I'll make it right with the owner.\"", truths: ("{DL} was seen carrying a mower from {V}'s shed.", "{V}'s son had set the mower out for trash."),
        defendant: [.direct("Where did you get it?", "\"I found it at the curb, set out with the trash.\""), .direct("Why say it was yours?", "\"To get a better price.\""),
                    .direct("Where did you find the mower?", "\"At the curb on a trash day, a few houses from where I live. It was sitting with a pile of old furniture.\""), .direct("Why did you take it?", "\"It looked like trash. The pull cord was frayed and the handle was loose, and I thought I could fix it and sell it.\""), .direct("What did you tell the buyer?", "\"That it was mine. I said that to get a better price, and I know that was not honest.\""), .direct("Did you look at the serial plate?", "\"No. I never checked it. I did not know it had been reported, and I did not look at any numbers.\""),
                    .cross("After your last case.", "\"I know. I should have known better after my last case.\""), .cross("The serial matches.", "\"I didn't look. I never checked whether the serial matched.\""),
                    .cross("The mower came from a shed, not a curb.", "\"I did not know that. I found it at the curb, and I did not go near anyone's shed.\""), .cross("You said it was yours.", "\"I did. I wanted $80, and I said what I thought would help me sell it.\""), .cross("You knew you should have asked whose it was.", "\"I did. I should have asked around the block before I took it. I did not, and I regret it.\"")],
        openings: ("{V}'s push mower vanished from a shed and a week later turned up at a weekend flea market, where {D} was selling it for $80. The serial plate matches {V}'s report, and a buyer says {D} claimed it was {D.his} own.", "The defense will say {D} found the mower at the curb on trash day, with a frayed cord, and that {V}'s son had actually set it out. {D} sold it openly at a public market with a price on it."), closings: ("The serial plate matches, a buyer was told the mower was {D}'s own, and a neighbor saw someone carrying a mower from {V}'s shed. {D} was back after {PRIOR}.", "A man who sells a trash-day mower at a public table with a price tag is not hiding. The State must prove {D} knew it was {V}'s and not abandoned."),
        timeline: [(0, "Weekend: mower for sale at the flea market.")], identified: "The buyer's call.", impact: "\"It's the second time something of mine ended up at a flea market, and it makes me angry every time. That mower was in my shed with the door closed, and someone sold it for a few dollars. I want it back, and I want the person to understand what it cost me.\"")

    static let leashThreat = followUp(
        key: "story.followup.leashThreat", category: .publicOrder,
        headlines: ["Dog Walk Dispute Turns to Threats", "Park Threat Charge After Earlier Assault Case"],
        law: "communicatingThreats", threshold: 5, spec: "Willfully threatened to physically injure {V}, in a manner a reasonable person would believe would be carried out, on {DATE}.", ages: 24...68, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} saw {V} at the same park and said, \"I'll put you on the ground again.\" {V} recorded the last words on a phone.",
        state: [E(.digital, 3, "Phone Recording", "{D}: \"I'll put you on the ground again.\""), E(.statement, 2, "Walker", "A walker heard it.")],
        defense: [E(.statement, 1, "Joke", "{D} says it was a joke between neighbors.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What does the recording say?", "\"'I'll put you on the ground again.'\""), .direct("What did {V} do?", "\"Left the park and called us.\""),
               .direct("What was the incident at the park?", "\"{V} was walking a dog when {DL}, who was at the same park, said, 'I'll put you on the ground again.' {V} recorded the last words on a phone.\""), .direct("What did a walker tell you?", "\"A walker nearby heard it, too. {V} had also laughed, and then {DL} said the words and followed {V} toward the parking lot.\""), .direct("Where did {V} go afterward?", "\"To the car. {V} drove out of the park and called us from the road. {V} was shaken and did not want to go back that day.\""), .direct("What was the earlier case about?", "\"A fall at the park. {DL} was in court over {PRIOR}, and {V} was the person who fell.\""),
                    .cross("{D.He} was smiling.", "\"We can't tell. I can't say whether {D.he} was smiling from the video.\""), .cross("Nothing happened.", "\"No. Nothing happened, and nobody was harmed.\""),
                    .cross("{DL} did not touch {V} that day?", "\"No. {D.He} walked toward {V}, and {V} left. Nothing physical happened.\""), .cross("The recording is only the last words?", "\"It starts mid-sentence. I cannot tell from it what came before or whether anyone laughed.\""), .cross("{DL} could have meant it as a joke?", "\"{DL} says so. A joke is possible, but {D.he} followed {V} to the car, and that is not funny to {V}.\"")],
        theory: ("{D} threatened {V} with another fall.", "A bad joke."),
        allocution: "\"I said that to {V} at the park in anger, and I'm sorry I did. I never meant to follow through, and I know how it sounds after the last time we were in this court. I'll stay out of that park from now on and keep my distance.\"", truths: ("{DL} followed {V} to the car.", "{V} had laughed first, a walker said."),
        defendant: [.direct("What did you mean?", "\"Nothing. It was a joke.\""), .direct("Why say it?", "\"I said it because I was nervous, and I didn't mean it.\""),
                    .direct("What did you say to {V}?", "\"I said, 'I'll put you on the ground again.' It was a joke we had traded as neighbors, about the time {V} slipped on the path.\""), .direct("Did {V} laugh first?", "\"A walker said so, and I think {V} did. We were both laughing about how clumsy we had been that day.\""), .direct("Why did you walk toward the parking lot?", "\"I was going to my own car. I was parked next to {V}, and I did not follow {V.him}.\""), .direct("Did you know {V} was recording?", "\"No. I did not see the phone. I would not have said it if I had known.\""),
                    .cross("After your last case.", "\"I know. My last case should have taught me to be careful, and it did not.\""), .cross("{V} didn't laugh.", "\"No. {V} didn't laugh, and I don't think it was funny to {V.him}.\""),
                    .cross("{V} was frightened enough to call the sheriff.", "\"I understand that. I should not have said it, and I am sorry it frightened {V.him}.\""), .cross("{V} did not laugh when you said it.", "\"I did not see that. I thought we were joking, and I misread it.\""), .cross("The words were about a fall that put {V} on the ground.", "\"They were. I know how that sounds after the earlier case, and I wish I could take it back.\"")],
        openings: ("{D} saw {V} at the same park and said, 'I'll put you on the ground again,' words {V} recorded on a phone, after the earlier case in which {V} was knocked down. A walker heard it, and {V} left the park and called deputies.", "The defense will say it was a joke between neighbors about the time {V} slipped on the path, that {V} had laughed first, and that {D} was walking to {D.his} own car. Nothing happened."), closings: ("'I'll put you on the ground again,' said to the person {D} had put on the ground before. {D} followed {V} toward the parking lot, and {V} left and called deputies.", "A neighbor's joke that was misread, and no one was touched. The State must prove {D} meant {V} to fear another fall and not merely to tease."),
        timeline: [(0, "Afternoon: {DL} meets {V} at the park.")], identified: "{V}'s recording.", impact: "\"I walk my dog before dawn now so I don't run into {DL}. At the park I was told I'd be put on the ground again, and I recorded the last words on my phone so I could prove it. I don't feel safe in a place I've used for years.\"")

    static let carClaimFalse = followUp(
        key: "story.followup.carClaimFalse", category: .whiteCollar,
        headlines: ["Insurance Claim Filed on Car Found at Girlfriend's House", "Insurance Fraud Charge After False Stolen Car Report"],
        law: "insuranceFraud", threshold: 6, spec: "Knowingly and with intent to defraud presented a written statement to an insurer, that {D.his} car had been stolen, in support of a claim for $9,400, on {DATE}.", ages: 20...58, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} filed a claim with the insurer saying the car had never been recovered, though a deputy had found it. The insurer paid $9,400, then learned the truth.",
        state: [E(.document, 3, "Claim Form", "{D} swore the car was not recovered; the deputy report says it was."), E(.document, 2, "Payment", "$9,400 paid to {D}.")],
        defense: [E(.statement, 1, "Paperwork Mix-Up", "{D} says the insurer never told {D.him} the car had been found.")],
        witnessRole: "Insurance special investigator",
        exam: [.direct("What did {DL} swear?", "\"That the car was never recovered.\""),
               .direct("What did the sheriff's report say?", "\"It was found two days after the report.\""),
               .direct("What was {DL}'s claim?", "\"That the car was stolen and never recovered. {D.He} signed a sworn claim form saying so, and asked for the full value.\""),
               .direct("What did the insurer do?", "\"We paid $9,400. We learned later that the car had been recovered, and I opened a fraud investigation.\""),
               .direct("What did you find when you looked for the car?", "\"It had been sold for parts. A salvage yard had the shell, and the yard's records show {DL} as the seller.\""),
               .direct("What did you do when you learned the car had been found?", "\"I reopened the file, asked the deputy for the recovery report, and traced the car to a salvage yard that bought it from {DL}.\""),
                    .cross("The insurer didn't tell {D.him}.", "\"They sent a letter. The insurer didn't call {D.him}, but they mailed a letter.\""),
               .cross("{D.He} may not have read it.", "\"Possible. {D.He} may not have read it.\""),
               .cross("The insurer sent {DL} a letter about the recovery?", "\"We mailed one to the address on the policy. We did not call, and I cannot say that {DL} read it.\""),
               .cross("A mix-up in the mail is possible, isn't it?", "\"It is possible. The letter went to the old apartment, and {DL} says {D.he} never got it.\""),
               .cross("The deputy's report also went to {DL}?", "\"The deputy called the owner's number and left a message. {DL} says {D.he} never got that either.\"")],
        theory: ("{D} swore to a false claim and took $9,400.", "A paperwork mix-up."),
        allocution: "\"I told the insurer the car was never recovered, and that was untrue, and I know it. I took nine thousand four hundred dollars I wasn't owed, and I'm ashamed of it. I'll pay every dollar back, and I won't make a claim like that again.\"", truths: ("{DL} sold the car for parts after the payment.", "The letter was addressed to the old apartment."),
        defendant: [.direct("Did you know it was found?", "\"No.\"", "\"I figured it was.\""),
               .direct("Why file?", "\"I needed the money. That's why I filed, and I know it was wrong.\""),
               .direct("Why did you file the claim?", "\"I needed the money. My car was gone, I owed on it, and I could not pay my bills.\""),
               .direct("Did you know the car had been found?", "\"Not when I filed. I found out later, and I did not tell the insurer. I was afraid of what would happen.\""),
               .direct("What did you do with the car?", "\"I sold it for parts after the check came. The car was already mine to sell, and I needed the cash.\""),
               .direct("Did the insurer contact you about the recovery?", "\"They mailed a letter, but it went to my old apartment. I did not get it until months later.\""),
               .direct("How do you feel about it now?", "\"I know I did wrong. I should have called the insurer when the sheriff's office left a message, and I did not.\""),
               .direct("What did you do with the insurance check?", "\"I paid back some debts and kept the rest. I told myself the car was gone anyway.\""),
                    .cross("After your last case.", "\"I know. I am here again after my last case, and I have no excuse.\""),
               .cross("You sold the car.", "\"I didn't think about it.\""),
               .cross("You swore the car was never recovered.", "\"At the time, it had not been, as far as I knew. I did not correct it when I learned otherwise.\""),
                    .cross("You sold the shell to a salvage yard.", "\"I did. I did not think it was a problem once the insurer had paid me for it.\""),
                    .cross("The insurer says it mailed a letter about the recovery.", "\"It went to an apartment I had moved out of, and I never saw it until months later.\"")],
        openings: ("{D} filed a claim saying the car was stolen and never recovered, though a deputy had found it two days after the report. The insurer paid $9,400 before learning the truth, and the car had been sold for parts by {D}.", "The defense will say a paperwork mix-up kept {D} from learning the car had been found, because the insurer's letter went to {D}'s old apartment. {D} did not know when the sworn claim was signed."), closings: ("A sworn claim that the car was never recovered, a deputy's report that it was found, $9,400 paid, and the shell sold for parts through {D}'s own account. {D} was back after {PRIOR}.", "A letter that went to the wrong apartment explains what {D} knew when {D.he} signed. The State must prove {D} knew the car had been recovered and kept the money anyway."),
        timeline: [(0, "Claim paid.")], identified: "The insurer's special investigations unit.", impact: nil)

    static let packageCardUse = followUp(
        key: "story.followup.packageCardUse", category: .whiteCollar,
        headlines: ["Card From Stolen Package Used at Dollar Store", "Card Fraud Charge After Porch Package Case"],
        law: "cardFraud", threshold: 5, spec: "Used a debit card belonging to {V}, a card issued in another person's name, to obtain $188 in goods, without consent, on {DATE}.", ages: 18...50, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s new debit card, mailed in a stolen envelope, was used three times at a dollar store for $188. The store camera showed {D}.",
        state: [E(.video, 3, "Store Camera", "{D} swipes the card three times."), E(.document, 2, "Bank Record", "Three charges totaling $188.")],
        defense: [E(.statement, 1, "Found Card", "{D} says {D.he} found the card on a sidewalk.")],
        witnessRole: "Dollar store clerk",
        exam: [.direct("What did you see?", "\"{DL} swiping a debit card three times.\""),
               .direct("Did {D.he} sign?", "\"No signature was needed. The paperwork didn't require {D.him} to sign anything.\""),
               .direct("How was the card connected to {V}?", "\"{V}'s new debit card was mailed in an envelope that was stolen from the mail before it reached {V.him}. {V} reported it the same day.\""),
               .direct("What does the store camera show?", "\"{DL} at the counter, polite and calm, with items on the belt, swiping the card three times without signing for any of it.\""),
               .direct("What did the bank records show?", "\"Three charges totaling $188 at the dollar store, all in one afternoon. No one used the card anywhere else.\""),
               .direct("Did the store keep the receipts?", "\"Yes. The three slips are in the register journal, with the time of each swipe and the last four digits of the card.\""),
                    .cross("{D.He} was polite.", "\"Very. {D.He} was polite the whole time.\""),
               .cross("{D.He} had a PIN.", "\"No. {D.He} used the credit option.\""),
               .cross("{DL} did not try to hide {D.his} face?", "\"No. {D.He} looked at the camera and paid like any customer. I noticed that.\""),
               .cross("The name on the card was not {DL}'s?", "\"The card said {V}'s name. {DL} did not say anything about that, and I did not check.\""),
               .cross("You do not know how {DL} got the card?", "\"No. All I know is what I saw at my register and what the bank told us.\"")],
        theory: ("{D} used a card that arrived in a stolen envelope.", "A found card."), allocution: "\"I thought it was a gift card, and I never saw a name on it. I used it three times at a dollar store. I'm sorry, and I should have asked. I'll pay {V} back.\"",
        truths: ("The envelope was found in {DL}'s trash.", "The envelope had been dropped on a sidewalk by a mail carrier."),
        defendant: [.direct("Where did you get the card?", "\"I found the card on the sidewalk.\""),
               .direct("Why use it?", "\"I thought it was a gift card.\""),
               .direct("Where did you find the card?", "\"On a sidewalk near the bus stop. It was lying in the open, and it looked like a gift card, plain with no name.\""),
               .direct("Why did you use it?", "\"I thought it was a gift card someone had dropped. I took it to the store to see if it still had money on it.\""),
               .direct("Did you read the name on the card?", "\"Not carefully. It was small, and I did not look at it. I only cared whether it worked.\""),
               .direct("How did you decide what to buy?", "\"Things I needed, like cleaning supplies and snacks. I did not buy anything big, and I was careful with the amounts.\""),
               .direct("What did you buy with the card?", "\"Cleaning supplies, snacks and a few things for the kitchen. Nothing large, and I kept the receipts.\""),
               .cross("After your last case.", "\"I know. Looking back, my last case should have made me far more careful.\""),
               .cross("Three swipes.", "\"I was shopping. The three swipes were me buying things I needed.\""),
               .cross("The card came in a stolen envelope.", "\"I did not know that. I only found a card on the ground, and I did not look for an envelope.\""),
               .cross("The card was mailed to {V} in an envelope that was stolen.", "\"I did not know that. I found a card on the sidewalk and did not look for an envelope.\""),
                    .cross("Nothing about that card looked like a gift card.", "\"It did to me, because it had no name on the front. I know the back had a bank logo, and I did not turn it over.\"")],
        openings: ("{V}'s new debit card was mailed in an envelope that was stolen from the mail, and three days later it was used three times at a dollar store for $188. The store camera shows {D} at the register swiping it.", "The defense will say {D} found the card on a sidewalk and believed it was a gift card, paid openly on camera, and never saw a stolen envelope. {D} bought ordinary things."), closings: ("A stolen envelope, a new card with {V}'s name on it, and {D} swiping it three times in twenty minutes without a signature. {D} was back after {PRIOR}.", "A card found on the ground and used openly in front of a camera is not hidden. The State must prove {D} knew it was stolen when {D.he} swiped it."),
        timeline: [(0, "Afternoon: card used three times.")], identified: "The dollar store's camera.", impact: "\"My new debit card was stolen from an envelope in my mailbox, and within a day it was used three times at a dollar store. The bank sorted it out eventually, but I was without my own money for over a week. I'm careful about the mail now, and I don't trust it anymore.\"")

    static let golfCartTrespass = followUp(
        key: "story.followup.golfCartTrespass", category: .property,
        headlines: ["Teen From Golf Cart Case Back on Same Subdivision Lot", "Trespass Charge After Golf Cart Ride"],
        law: "trespass2", threshold: 5, spec: "Entered and remained on the premises of {V}, a private subdivision pond, after being notified not to enter, on {DATE}.", ages: 18...24, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was found at 1 a.m. sitting by the same retention pond with a friend, after the homeowners' association had put up \"No Trespassing\" signs. {D.He} says he was walking home.",
        state: [E(.document, 2, "Posted Signs", "Three new signs at the pond path."), E(.statement, 2, "Association Letter", "{D} was told in writing to stay out.")],
        defense: [E(.statement, 1, "Walking Home", "{D} says the pond is on his usual route.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("Where was {DL}?", "\"Sitting by the pond at 1 a.m.\""),
               .direct("Was there a sign?", "\"Three. There were three signs posted.\""),
               .direct("What was the call?", "\"A resident reported two people sitting by the retention pond at about 1 a.m., after the association had posted No Trespassing signs.\""),
               .direct("Where was {DL} when you arrived?", "\"Sitting on the bank of the pond with a friend. {D.He} did not run and stood up when I shone my light.\""),
               .direct("What were the signs like?", "\"Three new signs along the pond path, with the association's name and a warning. They were reflective, and the writing was visible by flashlight.\""),
               .direct("What did the association's letter say?", "\"That {DL} was to stay out of the common areas, in writing. It was mailed after the earlier case.\""),
               .cross("{D.He} was walking home.", "\"By the pond? {D.He} was walking home, but I'm not sure which way {D.he} went.\""),
               .cross("Nothing was damaged.", "\"No. Nothing was damaged, and nobody was hurt.\""),
               .cross("{DL} lives close to the pond, doesn't {D.he}?", "\"Yes. The pond path is the only route to {D.his} apartment on foot, according to the map.\""),
               .cross("{DL} did not argue when you asked questions?", "\"No. {D.He} was calm. {D.He} said {D.he} was walking home and sat down because {D.he} was tired.\""),
                    .cross("{DL} did not damage the signs?", "\"No. The signs were intact, and I saw no damage to the pond or the fence.\"")],
        theory: ("{D} was told to stay out and sat by the pond.", "A route home."), allocution: "\"I was walking home that night, and the pond is on my way. I don't walk at night usually. I know the homeowner told us to stay out. I'll find another way home, and I'm sorry for the trespass.\"",
        truths: ("{DL} had thrown rocks into the pond that night.", "The pond path was the only route to {D.his} apartment."),
        defendant: [.direct("Why were you there?", "\"I was walking home when it happened.\""),
               .direct("Did you see the signs?", "\"Not at night. I didn't see the signs in the dark.\""),
               .direct("Why were you at the pond that night?", "\"I was walking home from a friend's place. The path along the pond is the only way to my apartment on foot.\""),
               .direct("Why did you sit down?", "\"I was tired after a long day, and my friend was with me. We sat for a few minutes before the deputy came.\""),
               .direct("Did you throw anything into the pond?", "\"No. A rock may have been thrown by someone earlier, and the deputy asked me about it. I did not throw anything.\""),
               .direct("Where does the pond path lead?", "\"To the back of my apartment complex. It is the only walkway from the bus stop, and I use it almost every night.\""),
                    .cross("After the golf cart.", "\"I know. After the golf cart I should have been more careful.\""),
               .cross("You sat down.", "\"I sat down because I was tired, not to make a point.\""),
               .cross("You got the letter from the association.", "\"I did, and I read it. I did not think it meant I could not walk to my own apartment.\""),
               .cross("You sat by the pond at one in the morning.", "\"I did. I know the hour looks bad, and I know I should have kept walking.\""),
                    .cross("You were told in writing to stay out of the common areas.", "\"I was, and I read the letter. I did not think it covered the path I use to get home.\"")],
        openings: ("The homeowners' association posted No Trespassing signs at the retention pond and wrote {D} that {D.he} was to stay out. At 1 a.m. a deputy found {D} sitting by the pond with a friend.", "The defense will say the pond path is the only way to {D}'s apartment, that {D} did not see the signs in the dark, and that {D} was walking home tired. {D} caused no damage."), closings: ("Three new signs, a written letter from the association, and {D} sitting at the pond at one in the morning, after {PRIOR}. {D} had been told to stay out.", "A man walking home on the only path to his apartment is not a trespasser by intent. The State must prove {D} knew the path was off limits."),
        timeline: [(0, "1 a.m.: {DL} found at the pond.")], identified: "A patrolling deputy.", impact: nil)

    static let refusedIDAgain = followUp(
        key: "story.followup.refusedIDAgain", category: .publicOrder,
        headlines: ["Man Who Refused ID Last Time Does It Again", "Second Resisting Charge After Refusal to Identify"],
        law: "resisting", threshold: 5, spec: "Willfully resisted, delayed, and obstructed a public officer, a sheriff's deputy, by refusing to identify {D.himself} during a lawful stop, on {DATE}.", ages: 24...62, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was stopped at a gas station parking lot after a clerk reported a man sleeping in a car. {DL} again refused to give a name. The deputy had a camera running.",
        state: [E(.video, 3, "Body Camera", "The deputy asks for a name three times; {D} refuses."), E(.document, 2, "Clerk's Report", "A man sleeping in a car for two hours.")],
        defense: [E(.statement, 1, "Rights", "{D} says he's not required to give a name.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What happened?", "\"I asked three times for a name. {DL} said no.\""), .direct("Was there a lawful reason for the stop?", "\"A report of a man asleep in a car.\""),
               .direct("What was the report?", "\"A gas station clerk called about a man who had been sleeping in a car in the lot for two hours, and asked us to check on him.\""), .direct("What happened when you approached?", "\"I knocked, and the man woke and rolled the window down. I asked for a name and he said he did not have to give one.\""), .direct("How many times did you ask?", "\"Three. I explained each time that I only wanted to know who he was, and each time he said no.\""), .direct("What did your camera record?", "\"The whole exchange, three requests and three refusals. {DL} stayed calm and did not get out.\""),
                    .cross("{DL} stayed calm.", "\"Yes. {DL} stayed calm the whole time.\""), .cross("Was he a danger?", "\"No. He wasn't a danger to anyone.\""),
                    .cross("{DL} did not do anything unlawful by sitting in a car, did he?", "\"Sleeping in a parked car in a lot is not a crime by itself. That is why I asked only for a name.\""), .cross("{DL} was not a danger to anyone?", "\"No. He did not threaten me and he kept his hands visible.\""), .cross("You later found a warrant in another county?", "\"I did, after I ran the plate. The name was part of why I wanted to identify him.\"")],
        theory: ("{D} refused again, after the court explained the law.", "A man asserting rights."), allocution: "\"I didn't think I had to give my ID to a deputy at a gas station. I was sleeping in my car. I know I was in this court before, and I understand now that I should have answered. I'll answer next time.\"",
        truths: ("{DL} had a warrant in another county.", "The clerk's call was a mistake; {D} was waiting for a tow."),
        defendant: [.direct("Why refuse?", "\"I don't have to. I'm not required to answer, so I refused.\""),
               .direct("Did you remember the last case?", "\"I did. I remembered the last case, and I should have thought about it first.\""),
               .direct("Why were you sleeping in the car?", "\"I was waiting for a tow truck. My car had broken down, and I was tired after a long day.\""),
               .direct("Why did you refuse to give your name?", "\"I do not have to. I am not required to answer a deputy who has no reason to arrest me, and I know my rights.\""),
               .direct("Did you remember the earlier case?", "\"I did. I remembered the last case, and I should have thought about it before I refused.\""),
               .direct("How did you treat the deputy?", "\"Politely. I kept my hands on the wheel and answered everything but my name.\""),
               .cross("You knew the risk.", "\"I know. I knew the risk, and I took it anyway.\""),
               .cross("Three requests.", "\"Yes. There were three requests, and I remember each one.\""),
               .cross("You were asked three times.", "\"I was. Each time I said no, and I could have given a name and ended it.\""),
               .cross("A clerk called because you had been there for two hours.", "\"I was waiting for the tow. I told the clerk, and I think the clerk forgot.\""),
                    .cross("You had a warrant in another county.", "\"I did not know that. If I had, I would have thought about it differently.\"")],
        openings: ("A gas station clerk reported a man sleeping in a car for two hours, and when a deputy asked {D} for a name three times on body camera, {D} refused each time. The deputy later found a warrant in another county.", "The defense will say {D} was waiting for a tow, is not required to give a name when no crime is suspected, and stayed calm. The clerk's call was a mistake."), closings: ("Three requests, three refusals, and a warrant in another county, after {D} had been told the law in the earlier case over {PRIOR}.", "A calm man waiting for a tow truck asserted a right the court has explained. The State must prove the deputy had a lawful reason to demand a name."),
        timeline: [(0, "Afternoon: deputy approaches the parked car.")], identified: "The deputy's body camera.", impact: nil)

    static let oxyRefill = followUp(
        key: "story.followup.oxyRefill", category: .drugs,
        headlines: ["Woman Charged With Altering Prescription for Pills", "Prescription Fraud Charge After Pill Bottle Case"],
        law: "prescriptionFraud", threshold: 6, spec: "Obtained a controlled substance by altering a prescription, changing a quantity from 10 to 40, on {DATE}.", ages: 25...64, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} handed a pharmacist a prescription whose quantity had been changed from 10 to 40. The pharmacist called the doctor's office, which had written 10.",
        state: [E(.document, 3, "Altered Prescription", "A \"1\" changed to a \"4\" in a different pen."), E(.statement, 2, "Doctor's Office", "The doctor wrote 10, not 40.")],
        defense: [E(.statement, 1, "Pain", "{D} says her back pain was unbearable and she didn't alter the paper.")],
        witnessRole: "Pharmacist",
        exam: [.direct("What did you notice?", "\"The 4 was in a different ink.\""), .direct("What did the doctor say?", "\"Ten. The doctor told me ten, and that's the number I remembered.\""),
               .direct("What did {DL} hand you?", "\"A prescription for oxycodone with the quantity written as 40. The '4' looked like a '1' that had been changed, in a different ink.\""), .direct("What did you do?", "\"I called the doctor's office, and they said the prescription was for 10 tablets. I noted the call and told {DL} I could not fill it.\""), .direct("What did the doctor's office say about the change?", "\"That they had written 10, not 40. The office manager checked the record and confirmed it.\""), .direct("How did {DL} react?", "\"Calmly. {D.He} said {D.he} did not know it had been changed and asked me to call the doctor myself.\""),
                    .cross("Anyone could have altered it.", "\"{DL} handed it to me.\""), .cross("{D.He} wasn't hostile.", "\"No. {D.He} wasn't hostile at any point.\""),
                    .cross("Someone else could have altered it before {DL} got it?", "\"It is possible. {DL} handed it to me, and I cannot say who changed it.\""), .cross("{DL} was not hostile?", "\"No. {D.He} was polite and waited while I called.\""), .cross("The doctor's receptionist later said something?", "\"She said she had written the number herself and corrected it later. I did not know that when I refused to fill it.\"")],
        theory: ("{D} altered a prescription to get thirty more pills.", "A handed-over paper that was already changed."),
        allocution: "\"I changed that prescription from ten pills to forty, and I did it because I was in pain and couldn't stand it. It was a terrible choice, and I know I put the pharmacist in a hard spot. I'm sorry, and I'm looking for help that doesn't involve breaking the law.\"", truths: ("{DL}'s pen matched the ink on the 4.", "The doctor's receptionist had changed the number herself and corrected it later."),
        defendant: [.direct("Did you alter it?", "\"No.\"", "\"Yes. I was in pain.\""),
               .direct("Where did you get it?", "\"From the doctor. It was prescribed to me, and I picked it up myself.\""),
               .direct("Why did you need the medicine?", "\"My back pain was unbearable. I had pain for months after a fall at work, and I needed relief.\""),
               .direct("Did you change the quantity?", "\"No. I did not touch the paper. I handed it to the pharmacist as I got it.\""),
               .direct("What did you do when the pharmacist refused?", "\"I asked to speak to the doctor. I left the paper with her, and I went home and called the office.\""),
               .direct("How long had you been on that medicine?", "\"About three weeks, after a fall at work. The doctor said ten tablets would get me through until my follow-up visit.\""),
               .direct("What did you tell the pharmacist when she said the number was wrong?", "\"That I did not know how that happened. I asked her to call the doctor, and I waited while she did.\""),
               .cross("After the bottle case.", "\"I know. After the bottle case, I should have been more careful.\""),
               .cross("Ink was different.", "\"I don't know. I can't say whether the ink was different.\""),
               .cross("A pen in your car matched the ink.", "\"I use a lot of pens. I could not tell you which one wrote on that paper.\""),
               .cross("The doctor's office says it wrote ten tablets.", "\"That is what they say. I picked up what the receptionist gave me, and I did not look at the number.\""),
                    .cross("The prescription you handed over had a number written in two inks.", "\"I did not look at it that closely. I gave it to the pharmacist the way the receptionist gave it to me.\"")],
        openings: ("{D} handed a pharmacist a prescription whose quantity had been changed from 10 to 40, in a different ink, and the doctor's office confirmed it had written 10. {D} had been before this court over {PRIOR} for pills.", "The defense will say {D} got the prescription from the doctor's office and handed it over as it was, in severe back pain. The receptionist later admitted she changed the number herself and corrected it afterward."), closings: ("A '1' turned into a '4' in a different pen on a prescription for oxycodone, {D}'s pen matched the ink, and the doctor had written ten. {D} was back after {PRIOR}.", "The doctor's receptionist later said she changed the number herself. The State must prove {D} altered the paper and knew the quantity was not what the doctor ordered."),
        timeline: [(0, "Afternoon: prescription presented.")], identified: "The pharmacist's call.", impact: nil)

    static let dineDashTwo = followUp(
        key: "story.followup.dineDashTwo", category: .property,
        headlines: ["Same Pair Skips Out on Another Diner Bill", "Second Walk-Out Charge for Diner Case Defendant"],
        law: "misdLarceny", threshold: 5, spec: "Stole $58 in food and service from a restaurant, on {DATE}.", ages: 19...52, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} and the same friend ate at a pizza place and left through a side door. The owner remembered the faces from a sheriff's flyer.",
        state: [E(.video, 3, "Restaurant Camera", "Two people leave through a side door without paying."), E(.document, 2, "Flyer", "A sheriff's flyer posted at three restaurants.")],
        defense: [E(.statement, 1, "Phone Call", "{D} says he stepped outside to take a phone call.")],
        witnessRole: "Restaurant owner",
        exam: [.direct("Who was it?", "\"The two from the flyer.\""), .direct("Which door?", "\"I went out the side door, which was the closest way out.\""),
               .direct("How did you recognize {DL}?", "\"A sheriff's flyer had been posted at three restaurants in town, with photos of two people who had left without paying. I knew the faces the moment they sat down.\""), .direct("What did they order?", "\"A large pizza, two salads and a pitcher of soda. The check came to a little over fifty dollars before the tip.\""), .direct("What did the restaurant camera show?", "\"Two people standing up from table six, walking to the side door, and leaving without stopping at the register. They did not look back.\""), .direct("Did you see them leave?", "\"I saw the side door open from the kitchen window. By the time I got to the dining room, the table was empty and the check was still on it.\""),
                    .cross("{DL} took a call.", "\"He left with his friend.\""), .cross("They came back?", "\"No. They never came back after that.\""),
                    .cross("{DL} says {D.he} left to take a phone call?", "\"That is what {D.he} says. {D.His} friend left with {D.him}, and the friend did not take a call.\""), .cross("Your side door is closer to the parking lot than the front?", "\"It is. It also does not pass the register, which is by the front door.\""), .cross("The friend paid the check the next day?", "\"Someone came by the next day and paid it. I did not see who, and the manager gave me the receipt later.\"")],
        theory: ("{D} did it again at a new restaurant.", "A phone call."), allocution: "\"A call came in as we ate, and I stepped away. My friend did pay later, but I know we left through the side door. I'm sorry to the owner, and I'll pay for the pizza.\"",
        truths: ("The pair had a list of restaurants taped inside a car window.", "{D}'s friend paid the check the next day."),
        defendant: [.direct("Why leave?", "\"I had to leave because I got a phone call I needed to take.\""),
               .direct("Did you pay?", "\"My friend did later. I forgot my wallet, and my friend paid afterward.\""),
               .direct("Why did you go to that restaurant?", "\"My friend and I wanted pizza. We had been there before, and we thought it would be an easy night out.\""),
               .direct("What did you do when you finished?", "\"We stood up and I walked toward the door because my phone was ringing. My friend said he would take care of the check.\""),
               .direct("Did you tell the waitress you were leaving?", "\"No. She was in the kitchen, and I did not see her. I was already out the door when I realized I had not paid.\""),
               .direct("What happened to the check?", "\"My friend paid it the next day. He went back alone and handed over cash, and I thought that settled it.\""),
               .cross("After the last case.", "\"I know. After the last case, I told myself it was over.\""),
               .cross("You left through a side door.", "\"It was closer. I used the side door because it was the nearest way out.\""),
               .cross("A flyer with your face was posted at three restaurants.", "\"I did not know that. I had seen one earlier case, and I told myself it was over.\""),
               .cross("Your friend left with you and did not stop.", "\"He was behind me. I did not think anything about it until later, and I should have.\""),
